-- Dark Chaos - passenger seats for downported mounts (2026-08-03)
-- Generated by retroport_tools/dc_mount_passenger_seats.py
--
-- The mount spells stay plain SPELL_AURA_MOUNTED (78). HandleAuraMounted reads
-- creature_template.VehicleId off the aura's misc creature and makes the PLAYER
-- the vehicle, so only VehicleId + a spellclick row are needed here.
--
-- REQUIRES the matching Vehicle.dbc / VehicleSeat.dbc rows (ids 1700+ / 10200+) to be
-- compiled and deployed to BOTH the client patch and the server dbc dir first --
-- a VehicleId with no Vehicle.dbc row leaves the mount with no vehicle kit.

-- 1) make each mount creature a vehicle
UPDATE `creature_template` SET `VehicleId`=1700 WHERE `entry`=3461287; -- Grand Expedition Yak (4 seats)
UPDATE `creature_template` SET `VehicleId`=1701 WHERE `entry`=3462402; -- Mighty Caravan Brutosaur (2 seats)
UPDATE `creature_template` SET `VehicleId`=1702 WHERE `entry`=3462403; -- Trader's Gilded Brutosaur (2 seats)
UPDATE `creature_template` SET `VehicleId`=1703 WHERE `entry`=3462501; -- Chauffeured Mechano-Hog (1 seats)

-- 2) let other players board (keyed by the MOUNT creature entry --
--    Unit::HandleSpellClick uses GetVehicleKit()->GetCreatureEntry())
DELETE FROM `npc_spellclick_spells` WHERE `npc_entry` IN (3461287,3462402,3462403,3462501);
INSERT INTO `npc_spellclick_spells` (`npc_entry`,`spell_id`,`cast_flags`,`user_type`) VALUES
(3461287,61424,1,0),
(3462402,61424,1,0),
(3462403,61424,1,0),
(3462501,61424,1,0);

-- spell 61424 = stock CONTROL_VEHICLE ride aura, BasePoints -1 -> first free seat.
-- entry range touched: 3461287..3462501
